{
  "thread": {
    "threadId": "thr-cpq-669923515fbccf80bc5068d03847acb0"
  },
  "messages": [
    {
      "schemaVersion": 1,
      "messageId": "msg-cf48bd1d-0b83-4154-835c-2416788dc5be",
      "thread": {
        "threadId": "thr-cpq-669923515fbccf80bc5068d03847acb0"
